// BAD: this key ships to every visitor's browser
const key = "sk-proj-abc123...";
fetch("https://api.openai.com/v1/chat", {
  headers: { Authorization: `Bearer ${key}` }
});

// browser -> your server -> OpenAI
// file: /api/chat.js  (runs on the server only)
const key = process.env.OPENAI_API_KEY; // stays server-side
// the browser just calls /api/chat, never OpenAI directly

// pseudo-code at the top of the route
if (!session) return res.status(401);        // must be logged in
if (await tooManyRequests(ip)) return res.status(429);
if (body.message.length > 2000) return res.status(413); // cap size

// BAD: trusts whatever id the browser sent
db.orders.find({ id: params.id })

// GOOD: tied to the logged-in user
db.orders.find({ id: params.id, userId: session.userId })

// validate first
const schema = z.object({ message: z.string().max(2000) });
const { message } = schema.parse(body); // throws on junk

// parameterised query: the ? is filled safely
db.query("SELECT * FROM notes WHERE title = ?", [message]);

// return this to the user
res.status(500).json({
  error: "Something went wrong",
  ref: "err_8f2a"   // you look this up in the logs
});
// the stack trace goes to the log, not the response
